from pathlib import Path

path = Path("backend/app/main.py")
raw = path.read_bytes()

try:
    source = raw.decode("utf-8-sig")
except UnicodeDecodeError:
    source = raw.decode("cp1252")

# 1. Normalize the area property generated by filter_forest_loss.py.
area_anchor = '    gdf = gpd.read_file(DETECTIONS_FILE)\n'

area_fix = '''    gdf = gpd.read_file(DETECTIONS_FILE)

    # Normalize the area property produced by the raster-to-GeoJSON pipeline.
    if "area_ha" not in gdf.columns and "area_hectares" in gdf.columns:
        gdf["area_ha"] = pd.to_numeric(
            gdf["area_hectares"],
            errors="coerce"
        )

'''

if 'gdf["area_ha"] = pd.to_numeric(' not in source:
    if area_anchor not in source:
        raise SystemExit("Could not find GeoJSON loading statement. No changes saved.")
    source = source.replace(area_anchor, area_fix, 1)

# 2. Make health report actual detection-data availability.
old_health = '''@app.get("/health")
def health_check():


    return {
        "status": "healthy",
        "project": "ForestWatch AI",
        "version": "1.1.0",
    }
'''

new_health = '''@app.get("/health")
def health_check():
    data_available = DETECTIONS_FILE.exists()

    return {
        "status": "healthy",
        "project": "ForestWatch AI",
        "version": "1.1.0",
        "detection_data": {
            "available": data_available,
            "file": str(DETECTIONS_FILE.relative_to(PROJECT_ROOT)),
            "message": (
                "Detection GeoJSON is available."
                if data_available
                else "Detection GeoJSON has not been generated or downloaded yet."
            ),
        },
    }
'''

if '"detection_data"' not in source:
    if old_health not in source:
        raise SystemExit("Could not match the existing health endpoint. No changes saved.")
    source = source.replace(old_health, new_health, 1)

# 3. Recognize the actual analysis-period metadata fields.
timeline_anchor = '        "after_date",'

timeline_fields = '''        "after_date",
        "before_period_start",
        "before_period_end",
        "after_period_start",
        "after_period_end",'''

if '"after_period_end"' not in source:
    if timeline_anchor not in source:
        raise SystemExit("Could not find timeline date-field list. No changes saved.")
    source = source.replace(timeline_anchor, timeline_fields, 1)

path.write_text(source, encoding="utf-8")
print("SUCCESS: Backend reliability improvements applied.")
print("1. area_hectares is normalized to area_ha.")
print("2. Health endpoint reports detection-data availability.")
print("3. Timeline recognizes analysis-period metadata.")
